@font-face {
	font-family: "Game Of Squids";
	font-weight: normal;
    font-style: normal;
	src: url("./fonts/Game-Of-Squids.otf") format("otf"),
	url("./fonts/Game-Of-Squids.eot") format("eot"),
	url("./fonts/Game-Of-Squids.woff2") format("woff2"),
	url("./fonts/Game-Of-Squids.woff")	format("woff");
}

*{
	margin: 0;
	padding: 0;
	text-decoration: none;
	box-sizing: border-box;
	font-family: sans-serif;
}

body{
	background: url(../img/dalgonabg.jpg);
	background-size: cover;
}

.widget__login{
    display: flex;
    flex-direction: column-reverse;
    align-items: center;
}

.widget__content{
	margin-top: 40px;
}

.box-form{
	display: flex;
	flex-direction: column;
	align-items: center;
	width: 35vw;
    padding: 3rem 1.5rem;
	background: rgb(0, 0, 0, 0.9);
	box-shadow: 0px 0px 22px #000;
	text-align: center;
}

.box .solution-text{
	font-family: "Game Of Squids";
	color: #ff00b2;
	padding: 0 50px;
	font-size: 1rem;
	width: 100%;
}

.box h1{
	color: #ff00b2;
}

.box span{
	color: #ff7ad7;
}

